    "svchost.exe", "services.exe", "lsass.exe", "system", "system.exe",
    "winlogon.exe", "csrss.exe", "smss.exe", "dwm.exe", "explorer.exe",
    "python.exe", "pythonw.exe", "cmd.exe", "powershell.exe",
}


