os.makedirs(FEEDS, exist_ok=True)

FEED_TTL = 30 * 60  # seconds
HASHES_URL = "https://bazaar.abuse.ch/export/txt/sha256/recent/"  # MalwareBazaar recent, no key
CACHE = os.path.join(FEEDS, "urlhaus_sha256.txt")

# skip huge/binary-irrelevant stuff when scanning a dir
SKIP_EXT = {".log", ".txt", ".md", ".json", ".csv", ".pyc", ".tmp"}
MAX_FILE_BYTES = 512 * 1024 * 1024


def refresh_cache():
    if os.path.exists(CACHE) and time.time() - os.path.getmtime(CACHE) < FEED_TTL:
        with open(CACHE) as f:
            return {l.strip().lower() for l in f if l.strip() and not l.startswith("#")}
    try:
        req = urllib.request.Request(HASHES_URL, headers={"User-Agent": "wd-40-shield"})
        with urllib.request.urlopen(req, timeout=60) as r:
            data = r.read().decode("utf-8", errors="replace")
        hashes = {l.strip().lower() for l in data.splitlines()
                  if l.strip() and not l.startswith("#")}
        with open(CACHE, "w") as f:
            f.write("\n".join(sorted(hashes)))
        return hashes
    except Exception as e:
        if os.path.exists(CACHE):
            print(f"[wd-40] WARNING: feed update failed ({e}); using stale cache")
            with open(CACHE) as f:
                return {l.strip().lower() for l in f if l.strip()}
        print(f"[wd-40] ERROR: no feed cache and update failed: {e}")
        return set()


def have_clamav():
    from shutil import which
    return bool(which("clamscan"))


def clamav_scan(path):
    """Return (flagged:bool, detail:str) via a real ClamAV scan."""
    import subprocess
    rc = subprocess.run(["clamscan", "--no-summary", "-i", path],
                        capture_output=True, text=True).returncode
    if rc == 1:  # virus(es) found
        return True, (subprocess.run(["clamscan", "-i", path],
                    capture_output=True, text=True).stdout or "clamav hit").strip()
    return False, ""


def sha256_of(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def collect(args):
    files = []
    it = iter(args)
    for a in it:
        if a == "--dir":
            folder = next(it, None)
            if not folder or not os.path.isdir(folder):
                print(f"[wd-40] not a directory: {folder}")
                continue
            for name in sorted(os.listdir(folder)):
                p = os.path.join(folder, name)
                if os.path.isfile(p) and os.path.splitext(name)[1].lower() not in SKIP_EXT:
                    files.append(p)
        else:
            files.append(a)
    return files


def main():
    args = sys.argv[1:]
    if not args:
        print(__doc__)
        return 2
    db = refresh_cache()
    print(f"[wd-40] MalwareBazaar cache loaded: {len(db)} known-bad SHA-256")
    if have_clamav():
        print("[wd-40] ClamAV engine: available (deep scan on)")
    else:
        print("[wd-40] ClamAV engine: NOT installed (hash check only — see clamav-setup.md)")

    hits = checked = 0
    for path in collect(args):
        if not os.path.isfile(path):
            print(f"[wd-40] ?? missing: {path}")
            continue
        if os.path.getsize(path) > MAX_FILE_BYTES:
            print(f"[wd-40] -- skipped (too big): {path}")
            continue
        digest = sha256_of(path)
        checked += 1
        info = digest in db
        if info:
            hits += 1
            print(f"[wd-40] !! MATCH {path}\n         sha256={digest}\n         source=URLhaus payload")
            continue  # already confirmed; skip ClamAV
        if have_clamav():
            flagged, detail = clamav_scan(path)
            if flagged:
                hits += 1
                print(f"[wd-40] !! MATCH {path}\n         ClamAV: {detail}")
    if hits:
        print(f"[wd-40] {hits}/{checked} file(s) MATCHED. Quarantine is YOUR call — nothing touched.")
        return 1
    print(f"[wd-40] {checked} file(s) clean.")
    return 0


if __name__ == "__main__":
    import urllib.parse
    sys.exit(main())

"""wd-40 IOC checker — step 2: network reputation.

Cross-checks network activity against free abuse.ch feeds:
  - Feodo Tracker : botnet C2 server IPs
  - URLhaus       : malware distribution URLs / hostnames

Feeds are cached in wd-40/feeds/ and refreshed at most every 30 min.

Usage:
    python wd-40/netcheck.py                 # check current connections (from watchdog baseline)
    python wd-40/netcheck.py <ip> [ip ...]   # check specific IPs
    python wd-40/netcheck.py <domain>        # anything non-IP is treated as a hostname
"""
import ipaddress
import json
import os
import re
import subprocess
import sys
import time
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
FEEDS = os.path.join(HERE, "feeds")
BASELINE = os.path.join(HERE, "logs", "baseline.json")
os.makedirs(FEEDS, exist_ok=True)

FEED_TTL = 30 * 60  # seconds

FEODO_URL = "https://feodotracker.abuse.ch/downloads/ipblocklist_recommended.txt"
URLHAUS_URL = "https://urlhaus.abuse.ch/downloads/text_recent/"


def fetch(url, dest, ttl=FEED_TTL):
    if os.path.exists(dest) and time.time() - os.path.getmtime(dest) < ttl:
        with open(dest) as f:
            return f.read()
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "wd-40-shield"})
        with urllib.request.urlopen(req, timeout=30) as r:
            data = r.read().decode("utf-8", errors="replace")
        with open(dest, "w") as f:
            f.write(data)
        return data
    except Exception as e:
        if os.path.exists(dest):
            with open(dest) as f:
                return f.read()  # stale cache better than nothing
        print(f"[wd-40] WARNING: could not update feed {url}: {e}")
        return ""


def load_feeds():
    feodo_raw = fetch(FEODO_URL, os.path.join(FEEDS, "feodo_ips.txt"))
    c2_ips = set(re.sub(r"^#", "", feodo_raw, flags=re.M).split())
    urlhaus_raw = fetch(URLHAUS_URL, os.path.join(FEEDS, "urlhaus_urls.txt"))
    bad_hosts = set()
    for line in urlhaus_raw.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        m = re.match(r"https?://([^/:]+)", line)
        if m:
            bad_hosts.add(m.group(1).lower())
    return c2_ips, bad_hosts


def local_connections():
    """Remote endpoints from the watchdog baseline (if present)."""
    if not os.path.exists(BASELINE):
        return []
    with open(BASELINE) as f:
        procs = json.load(f)["procs"]
    out = set()
    for pid, info in procs.items():
        for proto, local, remote, state in info["conns"]:
            host = remote.rsplit(":", 1)[0].strip("[]")
            if state in ("LISTEN", "") or host in ("0.0.0.0", "*", "::"):
                continue
            out.add((host, pid, info["name"]))
    return sorted(out)


def is_private(host):
    try:
        return ipaddress.ip_address(host).is_private
    except ValueError:
        return False


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("-")]
    c2_ips, bad_hosts = load_feeds()
    print(f"[wd-40] feeds loaded: {len(c2_ips)} C2 IPs, {len(bad_hosts)} malware hosts")

    targets = []
    if args:
        targets = [(a, "-", "cli") for a in args]
    else:
        conns = local_connections()
        if not conns:
            print("[wd-40] no baseline yet — run wd-40/watchdog.py first, or pass an IP/host")
            return
        targets = [(h, pid, name) for h, pid, name in conns if not is_private(h)]

    hits = 0
    for host, pid, name in targets:
        verdict = None
        try:
            if ipaddress.ip_address(host.strip("[]")) and host in c2_ips:
                verdict = "C2 SERVER (Feodo Tracker)"
        except ValueError:
            if host.lower() in bad_hosts:
                verdict = "MALWARE HOST (URLhaus)"
        if verdict:
            hits += 1
            print(f"[wd-40] !! MATCH {host} ({name}, pid {pid}) -> {verdict}")
    if hits:
        print(f"[wd-40] {hits} suspicious endpoint(s). Ask before quarantine — nothing killed automatically.")
    else:
        print("[wd-40] all checked endpoints clean.")


if __name__ == "__main__":
    main()

